74: function saveBlobToFile(data, filename) {
75:   if (data.size < 100) {
76:     throw new Error('下载失败')
77:   }
78:   const blob = new Blob([data])
79:   if ('download' in document.createElement('a')) {
80:     const elink = document.createElement('a')
81:     elink.download = filename
82:     elink.style.display = 'none'
83:     elink.href = URL.createObjectURL(blob)
84:     document.body.appendChild(elink)
85:     elink.click()
86:     URL.revokeObjectURL(elink.href)
87:     document.body.removeChild(elink)
88:   } else {
89:     navigator.msSaveBlob(blob, filename)
90:   }
91:   return data
92: }
