94: function handleDownloadError(reject) {
95:   return (r) => {
96:     if (r.response && r.response.data) {
97:       const handleErrorData = (data) => {
98:         try {
99:           const errorData = typeof data === 'string' ? JSON.parse(data) : data
100:           const errorMsg = errorData.msg || errorData.message || '操作失败'
101:           msgError(errorMsg)
102:           return reject(new Error(errorMsg))
103:         } catch (error) {
104:           msgError('操作失败，请稍后重试')
105:           return reject(new Error('操作失败，请稍后重试'))
106:         }
107:       }
108: 
109:       if (r.response.data instanceof Blob) {
110:         const reader = new FileReader()
111:         reader.onload = (e) => {
112:           handleErrorData(e.target.result)
113:         }
114:         reader.onerror = () => {
115:           msgError('操作失败，请稍后重试')
116:           return reject(new Error('操作失败，请稍后重试'))
117:         }
118:         reader.readAsText(r.response.data)
119:       } else {
120:         handleErrorData(r.response.data)
121:       }
122:     } else {
123:       msgError('操作失败，请稍后重试')
124:       return reject(new Error('操作失败，请稍后重试'))
125:     }
126:   }
127: }
