129: function createBlobDownloadRequest(requestPromise, filename) {
130:   return new Promise((resolve, reject) => {
131:     requestPromise
132:       .then((data) => resolve(saveBlobToFile(data, filename)))
133:       .catch(handleDownloadError(reject))
134:   })
135: }
