#!/usr/bin/env node
/**
 * check-page-rows.mjs —— 禅道 #6235 回归守卫
 *
 * 校验 paginateRows 同时兼容两种后端响应：
 *  1) queryHousesByBuildCode 忽略 pageNum，一次返回该楼幢全部户室；
 *  2) findHouseList 等接口后端已按页返回单页数据。
 * 防止「翻页仍是第一页」再次回归，也防止对已分页结果二次切片。
 */
import { paginateRows } from '../src/views/contract/utils/pageRows.js'

function expectEqual (actual, expected, label) {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    console.error('[check-page-rows] ' + label + ' 失败：实际 ' + JSON.stringify(actual) + '，期望 ' + JSON.stringify(expected))
    process.exit(1)
  }
}

const all = ['封闭空间', '架空层', '201', '202', '301', '601']

// 1) 全量结果：第 1 页 5 条、第 2 页剩余 1 条，total 保持真实总数
expectEqual(paginateRows(all, 6, 1, 5).rows, all.slice(0, 5), '全量第 1 页切片')
expectEqual(paginateRows(all, 6, 2, 5).rows, all.slice(5, 10), '全量第 2 页切片')
expectEqual(paginateRows(all, 6, 2, 5).total, 6, '全量 total')

// 2) 后端已分页：单页结果必须原样返回，不得再按 pageNum 切片
const serverPage = ['a', 'b', 'c', 'd', 'e']
expectEqual(paginateRows(serverPage, 6, 2, 5).rows, serverPage, '已分页结果不二次切片')
expectEqual(paginateRows(serverPage, 6, 2, 5).total, 6, '已分页 total')

// 3) 空列表、非法页码/页大小、缺省 total 的兜底
expectEqual(paginateRows([], 0, 1, 5), { rows: [], total: 0 }, '空列表')
expectEqual(paginateRows(all, undefined, 0, 0).rows, all.slice(0, 5), '非法页码兜底')
expectEqual(paginateRows(all, 6, 3, 5).rows, [], '越界页码')

console.log('[check-page-rows] 通过')

